with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Binary search misses the last element$$,
    $$python$$,
    $$off_by_one$$,
    $$hard$$,
    $$binary_search$$,
    $$def binary_search(nums, target):
    low = 0
    high = len(nums) - 1
    while low < high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1$$,
    $$def binary_search(nums, target):
    low = 0
    high = len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1$$,
    $$binary_search(nums, target) should return the index of target in a sorted list, or -1 if it isn't there.$$,
    $$It works for most values but returns -1 for some that are definitely present — searching for 9 in [1,3,5,7,9] gives -1.$$,
    $$The loop condition `low < high` exits when low and high meet, so the single remaining candidate is never checked. Binary search must keep going while the search window still contains one element, which means `low <= high`. Bugs like this hide well because they only show up when the target lands on the final narrowing step.$$,
    $$[{"input":[[1,3,5,7,9],9],"expected_output":4},{"input":[[1,3,5,7,9],1],"expected_output":0},{"input":[[1,3,5,7,9],5],"expected_output":2},{"input":[[1,3,5],4],"expected_output":-1}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$It only fails for certain targets. What do those targets have in common?$$ from new_challenge
union all
select id, 2, $$Think about the moment when low and high become equal — does the loop still run?$$ from new_challenge
union all
select id, 3, $$When low == high there is still one unchecked element. The condition should be low <= high.$$ from new_challenge;

