    $$[{"input":[{"first":"Ada","middle":"Byron","last":"Lovelace"}],"expected_output":"Ada Byron Lovelace"},{"input":[{"first":"Alan","last":"Turing"}],"expected_output":"Alan Turing"},{"input":[{"first":"Grace","middle":null,"last":"Hopper"}],"expected_output":"Grace Hopper"}]$$::jsonb,
